sys_script.script:
(function autoPopulateAllIssueFields(current, previous) {
    if (!current.u_issue_id || current.u_issue_id == '') {
        current.u_issue_id = 'ISS' + new Date().getTime().toString().slice(-7);
    }
    if (!current.u_department || current.u_department == '') current.u_department = 'dairy';
    if (!current.u_issue_type || current.u_issue_type == '') current.u_issue_type = 'inspection_failure';
    if (!current.u_assigned_to || current.u_assigned_to == '') current.u_assigned_to = '50b8f65cfd3603107f4456087f4cb1e3';
    if (!current.u_reported_by || current.u_reported_by == '') current.u_reported_by = '0cb8b2d0fd3603107f4456087f4cb160';
    if (!current.u_product || current.u_product == '') current.u_product = 'c596c3d8fdb603107f4456087f4cb189';
    if (!current.u_reported_date || current.u_reported_date == '') current.u_reported_date = gs.nowDate();
    if (!current.u_due_date || current.u_due_date == '') current.u_due_date = gs.daysAgo(-7);
})(current, previous);
